import{_ as t,o as e,c as i,a3 as s}from"./chunks/framework.D1iekJsc.js";const k=JSON.parse('{"title":"ComfyUI のインストール","description":"ComfyUI をインストールし LAN リスンを有効化、MiniTavern 画像接続でデフォルト workflow を使う。","frontmatter":{"title":"ComfyUI のインストール","description":"ComfyUI をインストールし LAN リスンを有効化、MiniTavern 画像接続でデフォルト workflow を使う。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"ComfyUI のインストール · MiniTavern Docs"}],["meta",{"property":"og:description","content":"ComfyUI をインストールし LAN リスンを有効化、MiniTavern 画像接続でデフォルト workflow を使う。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/local/image-gen/comfyui"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/local/image-gen/comfyui"}]]},"headers":[],"relativePath":"ja/local/image-gen/comfyui.md","filePath":"ja/local/image-gen/comfyui.md","lastUpdated":1787224147000}'),n={name:"ja/local/image-gen/comfyui.md"};function o(l,a,r,p,d,h){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="comfyui-のインストール" tabindex="-1">ComfyUI のインストール <a class="header-anchor" href="#comfyui-のインストール" aria-label="Permalink to &quot;ComfyUI のインストール&quot;">​</a></h1><p>ComfyUI はノード式のローカル生図フロントで、新モデル対応が速い。<br> MiniTavern は ComfyUI の HTTP API（<code>/prompt</code> など）に<strong>内蔵デフォルトワークフロー</strong>を送る；App 内でノード図を手書きしなくても出図できる。</p><p>公式ドキュメント：<a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">docs.comfy.org</a> · 倉庫：<a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">Comfy-Org/ComfyUI</a></p><h2 id="ハードウェア推奨" tabindex="-1">ハードウェア推奨 <a class="header-anchor" href="#ハードウェア推奨" aria-label="Permalink to &quot;ハードウェア推奨&quot;">​</a></h2><table tabindex="0"><thead><tr><th>显存</th><th>推奨</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5 など小さめワークフロー</td></tr><tr><td>8–12GB</td><td>SDXL、一部の高速 Flux 変体が現実的</td></tr><tr><td>Apple Silicon</td><td>ネイティブ可、同級 NVIDIA より遅いことが多い</td></tr></tbody></table><h2 id="方式-a-windows-ポータブル-推奨" tabindex="-1">方式 A：Windows ポータブル（推奨） <a class="header-anchor" href="#方式-a-windows-ポータブル-推奨" aria-label="Permalink to &quot;方式 A：Windows ポータブル（推奨）&quot;">​</a></h2><ol><li><a href="https://www.comfy.org/download" target="_blank" rel="noreferrer">ComfyUI リリース／公式ダウンロード</a>（またはコミュニティの <code>ComfyUI_windows_portable</code>）を開く。</li><li>システムドライブ以外へ解凍（パスは短く、中国語・空白なしが無難）。</li><li>NVIDIA なら <code>run_nvidia_gpu.bat</code>；CPU のみなら対応 CPU スクリプト。</li><li>本機ブラウザで表示されたアドレスを開く、よくあるのは：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><h2 id="方式-b-desktop-アプリ" tabindex="-1">方式 B：Desktop アプリ <a class="header-anchor" href="#方式-b-desktop-アプリ" aria-label="Permalink to &quot;方式 B：Desktop アプリ&quot;">​</a></h2><ol><li><a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">ComfyUI Desktop</a> をインストール。</li><li>設定 → Server Configuration（または類似の「サーバー／ネットワーク」）： <ul><li><strong>Listen Address</strong> を <code>0.0.0.0</code> に（既定 <code>127.0.0.1</code> だとスマホ不可）</li><li><strong>Port</strong> を控える（Desktop はよく <strong>8000</strong>、ポータブルの 8188 と異なる）</li></ul></li><li>再起動後、LAN IP でアクセス。</li></ol><h2 id="方式-c-手動-git-macos-linux-上級" tabindex="-1">方式 C：手動 Git（macOS／Linux／上級） <a class="header-anchor" href="#方式-c-手動-git-macos-linux-上級" aria-label="Permalink to &quot;方式 C：手動 Git（macOS／Linux／上級）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Comfy-Org/ComfyUI.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ComfyUI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows: venv\\Scripts\\activate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GPU に合わせて PyTorch をインストール（PyTorch 公式）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span></span></code></pre></div><h2 id="lan-の有効化-スマホ接続に必須" tabindex="-1">LAN の有効化（スマホ接続に必須） <a class="header-anchor" href="#lan-の有効化-スマホ接続に必須" aria-label="Permalink to &quot;LAN の有効化（スマホ接続に必須）&quot;">​</a></h2><h3 id="ポータブル-コマンドライン" tabindex="-1">ポータブル／コマンドライン <a class="header-anchor" href="#ポータブル-コマンドライン" aria-label="Permalink to &quot;ポータブル／コマンドライン&quot;">​</a></h3><p>起動スクリプト（例 <code>run_nvidia_gpu.bat</code>）を編集し、<code>main.py</code> の後に：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--listen</span></span></code></pre></div><p>完全例：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\python_embeded\\python.exe -s ComfyUI\\main.py --windows-standalone-build --listen</span></span></code></pre></div><table tabindex="0"><thead><tr><th>パラメータ</th><th>作用</th></tr></thead><tbody><tr><td><code>--listen</code></td><td>引数なしで全 NIC をリスンし、LAN アクセスを許可</td></tr><tr><td><code>--port 8188</code></td><td>任意でポート変更</td></tr><tr><td><code>--enable-cors-header</code></td><td>ブラウザ CORS が必要なとき；スマホ App 直連 API は通常不要</td></tr></tbody></table><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>上記：Listen を <code>0.0.0.0</code>、ポートは UI 準拠。</p><h2 id="モデルの配置" tabindex="-1">モデルの配置 <a class="header-anchor" href="#モデルの配置" aria-label="Permalink to &quot;モデルの配置&quot;">​</a></h2><p>checkpoint（<code>.safetensors</code>）を：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComfyUI/models/checkpoints/</span></span></code></pre></div><p>UI で <code>R</code> で一覧更新、または再起動。先に ComfyUI ウェブでデフォルト文生図が通ることを確認してから App 接続。</p><p>モデル入手例：<a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> · <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a>。</p><h2 id="検証" tabindex="-1">検証 <a class="header-anchor" href="#検証" aria-label="Permalink to &quot;検証&quot;">​</a></h2><p>本機：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><p>LAN（PC の IP に；Desktop はポート注意）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:8188</span></span></code></pre></div><p>スマホブラウザで同じアドレスが開けば、ネットワークとリスンは正常。</p><h2 id="minitavern-との差異-先に読む" tabindex="-1">MiniTavern との差異（先に読む） <a class="header-anchor" href="#minitavern-との差異-先に読む" aria-label="Permalink to &quot;MiniTavern との差異（先に読む）&quot;">​</a></h2><ul><li>App は<strong>内蔵デフォルト workflow</strong>を使い、だいたいマシン上の利用可能な checkpoint を選ぶ；複雑なカスタムノード図はサーバー側の変更が必要で、本チュートリアルの範囲外。</li><li>現行バージョンのデフォルト Comfy フローは<strong>参考図を使わない</strong>（参考図があってもエラーにはしない）；参考図で顔固定が必要なら <a href="./a1111">A1111</a> または参考図対応クラウドへ。</li><li>PC のスリープ／蓋閉じでサービス停止；IP 変更後は App の Base URL を更新。</li></ul><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><ul><li><a href="./connect-app">MiniTavern で設定</a></li><li>総覧：<a href="./index">画像モデル配備</a></li></ul>`,36)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
